// Month offsets retain year identity across rolling and multi-year selections.
let periodFilter={year:'2026',month:'all',range:'all'};
function periodDate(month,year=+state.year){const serial=year*12+Number(month);return{year:Math.floor(serial/12),month:((serial%12)+12)%12};}
let periodCoverageCache=null;
function suppliedPeriods(){const refs=['income','detail','balance','cashflow','pricing'].map(k=>finBook(k));if(periodCoverageCache&&periodCoverageCache.sbu===activeSbu&&refs.every((b,i)=>b===periodCoverageCache.refs[i]))return periodCoverageCache.values;const set=new Set();for(const kind of ['income','detail'])for(const r of records[kind]||[])if(r.value!==null)set.add(r.year*12+r.month);for(const kind of ['balance','cashflow','pricing']){const book=finBook(kind);if(!book)continue;const header=kind==='pricing'?1:5;for(const [cell,value]of Object.entries(book.cells)){const match=cell.match(/^([A-Z]+)(\d+)$/);if(!match||+match[2]!==header)continue;const p=parsePeriod(value);if(p&&Object.entries(book.cells).some(([a,v])=>a.startsWith(match[1])&&new RegExp('^'+match[1]+'[0-9]+$').test(a)&&+a.slice(match[1].length)>header&&typeof v==='number'))set.add(p.year*12+p.month);}}const values=[...set].sort((a,b)=>a-b);periodCoverageCache={sbu:activeSbu,refs,values};return values;}
function selectedPeriodSerials(){const supplied=suppliedPeriods();if(!supplied.length)return [];if(periodFilter.range!=='all'){const end=supplied.at(-1),count=+periodFilter.range;return Array.from({length:count},(_,i)=>end-count+1+i);}return supplied.filter(s=>(periodFilter.year==='all'||Math.floor(s/12)===+periodFilter.year)&&(periodFilter.month==='all'||s%12===+periodFilter.month));}
ids=function(){return selectedPeriodSerials().map(s=>s-(+state.year)*12);};
period=function(){const list=selectedPeriodSerials(),fmt=s=>months[s%12]+' '+Math.floor(s/12);return !list.length?'No supplied period':list.length===1?fmt(list[0]):periodFilter.month!=='all'&&periodFilter.range==='all'?months[+periodFilter.month]+' · '+(periodFilter.year==='all'?'all years':periodFilter.year):fmt(list[0])+' – '+fmt(list.at(-1));};
val=function(r,type='Actual',kind='income',selected=ids(),year=+state.year){const values=selected.map(m=>{const p=periodDate(m,+year);return records[kind]?.find(x=>x.r===r&&x.year===p.year&&x.month===p.month&&x.type===type)?.value??null;});return values.length&&values.every(Number.isFinite)?values.reduce((a,b)=>a+b,0):null;};
const periodFinColumn=finColumn;finColumn=function(k,year,month){const p=periodDate(month,+year);return periodFinColumn(k,p.year,p.month);};
const periodPriceValue=priceValue;priceValue=function(p,metric,month=ids().at(-1),year=+state.year){const date=periodDate(month,year);return periodPriceValue(p,metric,date.month,date.year);};
const periodEquityClosing=equityClosing;equityClosing=function(month=ids().at(-1),year=+state.year){const p=periodDate(month,year);return periodEquityClosing(p.month,p.year);};
priorPeriod=function(){return periodDate(ids()[0]-1);};
reviewMonths=function(){return ids();};
economicsMonths=function(){const ms=ids();if(economicsDuration==='3'||economicsDuration==='6')return ms.slice(-Number(economicsDuration));return ms;};
chart=function(r){return reviewChart(label(r),[{name:'Actual',values:ids().map(m=>val(r,'Actual','income',[m]))},{name:'Budget',values:ids().map(m=>val(r,'Budget','income',[m]))}],ids().map(m=>periodMonthLabel(m)));};
function periodMonthLabel(m){const p=periodDate(m);return months[p.month]+' '+p.year;}
source=function(r,kind='income'){const selected=new Set(selectedPeriodSerials());$('evidenceBody').innerHTML=`<h2>${esc(label(r,kind))}</h2><p>${esc(data[kind].name)} · ${esc(data[kind].sheet)}</p><p>Raw source units. Missing selected months leave aggregate results blank.</p>${table(['Period','Type','Cell','Raw value'],records[kind].filter(x=>x.r===r&&selected.has(x.year*12+x.month)).map(x=>[months[x.month]+' '+x.year,x.type,x.cell,num(x.value,4)]))}`;$('evidence').showModal();};
const periodRender=render;render=function(){const supplied=suppliedPeriods(),years=[...new Set(supplied.map(s=>Math.floor(s/12)))];if(periodFilter.year!=='all'&&!years.includes(+periodFilter.year))periodFilter.year=String(years.at(-1)||state.year);state.year=periodFilter.range!=='all'||periodFilter.year==='all'?(years.at(-1)||+state.year):+periodFilter.year;const selected=selectedPeriodSerials(),offsets=selected.map(s=>s-state.year*12);state.period=offsets.length===1?String(offsets[0]):'ytd';state.cutoff=offsets.at(-1)??0;for(const m of offsets){if(m<0||m>11)Object.defineProperty(months,String(m),{value:periodMonthLabel(m),configurable:true,writable:true,enumerable:false});}periodRender();if(state.view==='upload')return;const year=$('year'),oldPeriod=$('period'),cutoff=$('cutoff');if(year)year.parentElement.remove();if(oldPeriod)oldPeriod.parentElement.remove();if(cutoff)cutoff.parentElement.remove();const area=document.createElement('div');area.className='period-filter-controls';area.innerHTML=select('filterYear','Year',[['all','All years'],...years.map(y=>[y,y])],periodFilter.year)+select('filterMonth','Month',[['all','All months'],...months.map((m,i)=>[i,m])],periodFilter.month)+select('filterRange','Specific period',[['all','All months / selected year & month'],['1','Last 1 month'],['3','Last 3 months'],['6','Last 6 months'],['12','Last 1 year'],['24','Last 2 years']],periodFilter.range)+`<small class="period-summary">${esc(period())}${periodFilter.range!=='all'?' · rolling period through latest source month':''}</small>`;$('toolbar').prepend(area);$('filterYear').disabled=$('filterMonth').disabled=periodFilter.range!=='all';for(const [id,key]of [['filterYear','year'],['filterMonth','month'],['filterRange','range']])$(id).onchange=e=>{periodFilter[key]=e.target.value;render();};if($('economicsYear')){$('economicsYear').value=state.year;$('economicsYear').onchange=e=>{periodFilter.year=e.target.value;periodFilter.range='all';render();};}};
